import{_ as a,o as s,c as l,a3 as o}from"./chunks/framework.Cc-oPviL.js";const u=JSON.parse('{"title":"04 · 记忆与 MCP：让 Agent 记得住、接得上","description":"","frontmatter":{},"headers":[],"relativePath":"ai/agent/04.md","filePath":"ai/agent/04.md"}'),n={name:"ai/agent/04.md"};function i(r,t,e,d,c,h){return s(),l("div",null,[...t[0]||(t[0]=[o(`<h1 id="_04-·-记忆与-mcp-让-agent-记得住、接得上" tabindex="-1">04 · 记忆与 MCP：让 Agent 记得住、接得上 <a class="header-anchor" href="#_04-·-记忆与-mcp-让-agent-记得住、接得上" aria-label="Permalink to &quot;04 · 记忆与 MCP：让 Agent 记得住、接得上&quot;">​</a></h1><blockquote><p><strong>学完你能说出</strong>：</p><ul><li>短期记忆和长期记忆分别是什么、存在哪、怎么用。</li><li>上下文太长时的三种处理办法：截断、摘要、存到外部再检索。</li><li>MCP 是什么，解决了什么问题（用「USB 接口」讲清楚）。</li></ul></blockquote><h2 id="先看地图" tabindex="-1">先看地图 <a class="header-anchor" href="#先看地图" aria-label="Permalink to &quot;先看地图&quot;">​</a></h2><p>前面讲了 Agent 怎么想、怎么做。这一篇解决两个「工程问题」：</p><ul><li><strong>记忆</strong>：任务一长，聊天记录塞不下了怎么办？下次对话还记得用户的偏好吗？</li><li><strong>接入</strong>：工具越来越多，每接一个都要写一套代码，能不能统一？</li></ul><p>本篇讲 4 个点：① 短期记忆 → ② 长期记忆 → ③ MCP 是什么 → ④ 为什么需要 MCP。</p><h2 id="一句话本质" tabindex="-1">一句话本质 <a class="header-anchor" href="#一句话本质" aria-label="Permalink to &quot;一句话本质&quot;">​</a></h2><ul><li><strong>记忆 = 决定把哪些信息留在上下文里、哪些存到外面，需要时再取回来。</strong></li><li><strong>MCP = AI 应用和外部工具之间的一套通用接口标准，接一次就能用。</strong></li></ul><h2 id="生活类比" tabindex="-1">生活类比 <a class="header-anchor" href="#生活类比" aria-label="Permalink to &quot;生活类比&quot;">​</a></h2><ul><li><strong>短期记忆</strong>像<strong>工作台</strong>：桌面就那么大（上下文窗口），只能放手头正在用的东西。</li><li><strong>长期记忆</strong>像<strong>档案柜</strong>：东西多也放得下，但要用的时候得去翻（检索）。</li><li><strong>MCP</strong> 像 <strong>USB-C 接口</strong>：以前每个设备一种充电线，现在一个标准接口，什么设备都能插。</li></ul><h2 id="一步步看" tabindex="-1">一步步看 <a class="header-anchor" href="#一步步看" aria-label="Permalink to &quot;一步步看&quot;">​</a></h2><h3 id="_1-短期记忆-上下文里的对话历史" tabindex="-1">1. 短期记忆：上下文里的对话历史 <a class="header-anchor" href="#_1-短期记忆-上下文里的对话历史" aria-label="Permalink to &quot;1. 短期记忆：上下文里的对话历史&quot;">​</a></h3><p>就是第 04 篇说的「每次把历史消息重新发一遍」。Agent 每走一步，Thought、Action、Observation 都会追加进去，很快就变长。</p><p>太长了怎么办？三种办法：</p><table tabindex="0"><thead><tr><th>办法</th><th>怎么做</th><th>代价</th></tr></thead><tbody><tr><td><strong>截断</strong></td><td>只保留最近 N 轮</td><td>早期信息直接丢了</td></tr><tr><td><strong>摘要</strong></td><td>用模型把旧的对话压缩成一段总结</td><td>细节会丢，还要额外调用模型</td></tr><tr><td><strong>外存 + 检索</strong></td><td>旧内容存进向量库，需要时按相关性取回</td><td>实现复杂，可能取不准</td></tr></tbody></table><h3 id="_2-长期记忆-跨对话保存" tabindex="-1">2. 长期记忆：跨对话保存 <a class="header-anchor" href="#_2-长期记忆-跨对话保存" aria-label="Permalink to &quot;2. 长期记忆：跨对话保存&quot;">​</a></h3><p>比如用户说过「我在准备 AI 应用岗的面试」，下次对话还应该记得。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>写入：对话中出现值得记住的信息 → 提取成一条记忆 → 存进数据库（常配向量，方便检索）</span></span>
<span class="line"><span>读取：新对话开始 / 遇到相关问题 → 检索相关记忆 → 放进上下文</span></span></code></pre></div><p>这和 RAG 的思路几乎一样：<strong>把资料换成「关于用户的记忆」而已。</strong></p><h3 id="_3-mcp-工具的统一接口" tabindex="-1">3. MCP：工具的统一接口 <a class="header-anchor" href="#_3-mcp-工具的统一接口" aria-label="Permalink to &quot;3. MCP：工具的统一接口&quot;">​</a></h3><p><strong>MCP（Model Context Protocol，模型上下文协议）</strong> 是 Anthropic 在 2024 年底发布的开放标准。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>AI 应用（MCP 客户端）  ←— 统一协议 —→  MCP 服务器 A：文件系统</span></span>
<span class="line"><span>                                     MCP 服务器 B：GitHub</span></span>
<span class="line"><span>                                     MCP 服务器 C：数据库</span></span></code></pre></div><ul><li><strong>MCP 服务器</strong>：把某个外部能力包装成标准格式，对外提供： <ul><li><strong>工具（Tools）</strong>：可以调用的操作，比如「创建 issue」；</li><li><strong>资源（Resources）</strong>：可以读取的数据，比如「某个文件的内容」；</li><li><strong>提示模板（Prompts）</strong>：预先写好的常用提示。</li></ul></li><li><strong>MCP 客户端</strong>：AI 应用里负责连接服务器的部分。连上后就能拿到工具列表，像上一篇那样交给模型调用。</li></ul><h2 id="为什么这么设计" tabindex="-1">为什么这么设计 <a class="header-anchor" href="#为什么这么设计" aria-label="Permalink to &quot;为什么这么设计&quot;">​</a></h2><h3 id="为什么要区分短期记忆和长期记忆" tabindex="-1">为什么要区分短期记忆和长期记忆？ <a class="header-anchor" href="#为什么要区分短期记忆和长期记忆" aria-label="Permalink to &quot;为什么要区分短期记忆和长期记忆？&quot;">​</a></h3><ul><li><strong>问题</strong>：上下文窗口有限、按 Token 计费；但有些信息（用户偏好、历史结论）需要长期保留。</li><li><strong>方案</strong>：当前任务相关的放在上下文（短期），需要长期保留的存到外部数据库（长期），用时检索。</li><li><strong>好处</strong>：上下文不会无限膨胀，重要信息也不会丢。</li></ul><div class="tip custom-block"><p class="custom-block-title">一句话答法</p><p>上下文窗口有限且昂贵，只能放当前需要的信息；长期信息存到外部、按需检索，兼顾容量和成本。</p></div><h3 id="为什么需要-mcp" tabindex="-1">为什么需要 MCP？ <a class="header-anchor" href="#为什么需要-mcp" aria-label="Permalink to &quot;为什么需要 MCP？&quot;">​</a></h3><ul><li><strong>问题</strong>：以前每个 AI 应用接每个工具都要单独写对接代码。M 个应用 × N 个工具 = M × N 套代码，重复劳动，还各不兼容。</li><li><strong>方案</strong>：定一个统一协议。工具方写一次 MCP 服务器，所有支持 MCP 的应用都能用；应用方实现一次 MCP 客户端，就能接所有服务器。</li><li><strong>好处</strong>：M × N 变成 M + N；工具可以复用，生态能共享。</li></ul><div class="tip custom-block"><p class="custom-block-title">一句话答法</p><p>MCP 统一了 AI 应用和外部工具之间的接口，把 M×N 的定制对接变成 M+N：工具写一次服务器，所有支持 MCP 的应用都能直接用。</p></div><h3 id="mcp-和-function-calling-是什么关系" tabindex="-1">MCP 和 Function Calling 是什么关系？ <a class="header-anchor" href="#mcp-和-function-calling-是什么关系" aria-label="Permalink to &quot;MCP 和 Function Calling 是什么关系？&quot;">​</a></h3><ul><li><strong>Function Calling</strong>：模型层面的能力，指模型「按格式说出要调哪个工具」。</li><li><strong>MCP</strong>：应用和工具之间的连接标准，管的是「工具从哪来、怎么接进来、怎么执行」。</li><li><strong>两者配合</strong>：MCP 把工具列表提供给应用 → 应用通过 Function Calling 交给模型 → 模型选择工具 → 应用再通过 MCP 去执行。</li></ul><div class="tip custom-block"><p class="custom-block-title">一句话答法</p><p>Function Calling 解决「模型怎么表达要调用工具」，MCP 解决「应用怎么以统一方式接入和执行外部工具」，两者是上下游关系，不是替代关系。</p></div><h2 id="英文术语拆解" tabindex="-1">英文术语拆解 <a class="header-anchor" href="#英文术语拆解" aria-label="Permalink to &quot;英文术语拆解&quot;">​</a></h2><table tabindex="0"><thead><tr><th>术语</th><th>拆开看</th><th>一句话意思</th></tr></thead><tbody><tr><td>Short-term Memory</td><td>short-term 短期 + memory 记忆</td><td>短期记忆：当前上下文里的对话历史</td></tr><tr><td>Long-term Memory</td><td>long-term 长期 + memory</td><td>长期记忆：存在外部、跨会话的信息</td></tr><tr><td>Summarization</td><td>summary 摘要 + -ization 化</td><td>摘要：把长内容压缩成要点</td></tr><tr><td>MCP</td><td>Model 模型 + Context 上下文 + Protocol 协议</td><td>模型上下文协议，AI 接外部工具的统一标准</td></tr><tr><td>Client / Server</td><td>客户端 / 服务器</td><td>发起连接的一方 / 提供能力的一方</td></tr><tr><td>Resource</td><td>资源</td><td>MCP 里可读取的数据</td></tr><tr><td>Protocol</td><td>协议</td><td>双方约定好的通信规则</td></tr></tbody></table><h2 id="面试怎么问" tabindex="-1">面试怎么问 <a class="header-anchor" href="#面试怎么问" aria-label="Permalink to &quot;面试怎么问&quot;">​</a></h2><p><strong>Q：Agent 的记忆怎么设计？</strong></p><blockquote><p>短期记忆是当前上下文里的对话和执行记录，超长时用截断、摘要或滑动窗口处理；长期记忆把关键信息（用户偏好、历史结论）提取出来存进数据库，常用向量检索按需召回。还要考虑写入策略（什么值得记）和过期、更新。</p></blockquote><p><strong>Q：什么是 MCP？解决了什么问题？</strong></p><blockquote><p>MCP 是 Anthropic 提出的开放协议，标准化了 AI 应用与外部数据源、工具之间的连接，采用客户端-服务器架构，服务器可以暴露工具、资源和提示模板。它把每个应用对接每个工具的 M×N 问题变成 M+N，提高复用性和互操作性。</p></blockquote><p><strong>Q：MCP 和 Function Calling 的区别？</strong></p><blockquote><p>Function Calling 是模型生成结构化工具调用请求的能力；MCP 是应用与工具提供方之间的接入协议。MCP 负责发现和执行工具，Function Calling 负责让模型选择和调用工具，两者通常配合使用。</p></blockquote><h2 id="容易混的地方" tabindex="-1">容易混的地方 <a class="header-anchor" href="#容易混的地方" aria-label="Permalink to &quot;容易混的地方&quot;">​</a></h2><ul><li><strong>模型本身不会「记住」你</strong>：所谓记忆，全是应用在外部存、在需要时再塞进上下文。</li><li><strong>MCP 不是一个模型，也不是某个产品</strong>：它是一份协议（规则），各家都可以实现。</li><li><strong>接了 MCP 不代表安全</strong>：第三方 MCP 服务器能执行操作、能读数据，同样要做权限控制（见下一篇）。</li></ul><h2 id="和其他知识的连接" tabindex="-1">和其他知识的连接 <a class="header-anchor" href="#和其他知识的连接" aria-label="Permalink to &quot;和其他知识的连接&quot;">​</a></h2><ul><li><strong>← 来自</strong> <a href="/study-hub/ai/agent/03">ReAct 与规划</a>：步骤多了，历史变长，才需要记忆管理。</li><li><strong>← 来自</strong> <a href="/study-hub/ai/rag/01">RAG 是什么</a>：长期记忆的读取，本质就是一次 RAG 检索。</li><li><strong>← 来自</strong> <a href="/study-hub/ai/agent/02">工具调用</a>：MCP 提供工具，Function Calling 使用工具。</li><li><strong>类比</strong> <a href="/study-hub/bagu/network/01">分层模型与一次请求的一生</a>：网络靠统一协议让不同设备互通，MCP 靠统一协议让不同工具互通。</li></ul><h2 id="自测-3-问" tabindex="-1">自测 3 问 <a class="header-anchor" href="#自测-3-问" aria-label="Permalink to &quot;自测 3 问&quot;">​</a></h2><p><strong>Q1：对话历史太长时，有哪三种处理办法？各有什么代价？</strong></p><details class="details custom-block"><summary>点开看答案</summary><p>① <strong>截断</strong>：只保留最近几轮，早期信息丢失；② <strong>摘要</strong>：压缩旧对话，丢细节、要多调一次模型；③ <strong>外存 + 检索</strong>：存进向量库按需取回，实现复杂、可能取不准。</p></details><p><strong>Q2：用「USB-C」类比解释 MCP 解决的问题。</strong></p><details class="details custom-block"><summary>点开看答案</summary><p>以前每个设备一种充电线（每个应用接每个工具都要单独写代码，M×N 套）；USB-C 统一了接口（MCP 统一了协议），工具写一次服务器、应用实现一次客户端，就能互相接上（M+N）。</p></details><p><strong>Q3：MCP 和 Function Calling 是什么关系？</strong></p><details class="details custom-block"><summary>点开看答案</summary><p>上下游关系。MCP 负责把外部工具以统一方式接入应用并执行；Function Calling 负责让模型从工具列表里选择、并生成调用请求。应用通过 MCP 拿到工具 → 交给模型 → 模型发出调用请求 → 应用通过 MCP 执行。</p></details><h2 id="✅-验收清单" tabindex="-1">✅ 验收清单 <a class="header-anchor" href="#✅-验收清单" aria-label="Permalink to &quot;✅ 验收清单&quot;">​</a></h2><ul><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="0"> 能用「工作台 / 档案柜」类比区分短期和长期记忆</li><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="1"> 能说出上下文过长的三种处理办法及代价</li><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="2"> 能说出长期记忆的写入和读取流程，并指出它和 RAG 的相似之处</li><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="3"> 能讲清 MCP 为什么能把 M×N 变成 M+N（问题 → 方案 → 好处）</li><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="4"> 能说清 MCP 和 Function Calling 的关系</li></ul><h2 id="下一步该懂什么" tabindex="-1">下一步该懂什么 <a class="header-anchor" href="#下一步该懂什么" aria-label="Permalink to &quot;下一步该懂什么&quot;">​</a></h2><ul><li>Agent 能动手了，怎么防止它被诱导干坏事？怎么评估它做得好不好？→ <a href="/study-hub/ai/agent/05">安全与评估</a></li></ul>`,57)])])}const p=a(n,[["render",i]]);export{u as __pageData,p as default};
